using System.ComponentModel;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---
var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run the research agent.");

var topic = args.Length > 0
    ? string.Join(' ', args)
    : PromptForTopic();

Console.WriteLine($"\n🔍 Research Agent — topic: \"{topic}\"\n");

// --- Build the chat client with tool support ---
IChatClient client = new OpenAIClient(apiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()   // automatically invokes tools when the model requests them
    .Build();

// --- Register tools ---
var notebook = new Notebook();
var chatOptions = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(WebSearchTool.SearchWeb),
        AIFunctionFactory.Create(WebSearchTool.FetchPage),
        AIFunctionFactory.Create(notebook.SaveNote),
        AIFunctionFactory.Create(notebook.ListNotes),
    ]
};

// --- System prompt ---
var systemPrompt = """
    You are a research agent. Your goal is to research the user-provided topic
    thoroughly and produce a concise, well-structured summary.

    Workflow:
    1. Use the SearchWeb tool to find relevant information (try 2-3 different queries).
    2. Use the FetchPage tool to read promising pages.
    3. Use the SaveNote tool to record key facts and source URLs as you go.
    4. Use the ListNotes tool to review what you have collected.
    5. Once you have enough material, write a final summary that synthesizes your notes.
       Include inline source references.

    Be methodical: search, read, note, then summarize.
    """;

// --- Agentic conversation loop ---
List<ChatMessage> messages =
[
    new(ChatRole.System, systemPrompt),
    new(ChatRole.User, $"Research the following topic and provide a summary:\n\n{topic}"),
];

const int maxTurns = 20;
for (var turn = 0; turn < maxTurns; turn++)
{
    var response = await client.GetResponseAsync(messages, chatOptions);

    // Append all response messages to the conversation history
    foreach (var msg in response.Messages)
        messages.Add(msg);

    // If the model made tool calls, the FunctionInvocation middleware already
    // executed them and appended tool-result messages. Loop so the model can
    // react to those results. If no tool calls were made, the model is done.
    bool hadToolCall = response.Messages
        .Any(m => m.Contents.OfType<FunctionCallContent>().Any());

    if (!hadToolCall)
    {
        // Final assistant message is the summary
        var final = response.Messages.LastOrDefault(m => m.Role == ChatRole.Assistant);
        Console.WriteLine("═══════════════════════════════════════════");
        Console.WriteLine("  RESEARCH SUMMARY");
        Console.WriteLine("═══════════════════════════════════════════\n");
        Console.WriteLine(final?.Text ?? "(no summary produced)");
        Console.WriteLine();
        break;
    }

    Console.WriteLine($"  … agent working (turn {turn + 1})");
}

// Show collected notes
if (notebook.Notes.Count > 0)
{
    Console.WriteLine("───────────────────────────────────────────");
    Console.WriteLine($"  📒 {notebook.Notes.Count} note(s) saved during research");
    Console.WriteLine("───────────────────────────────────────────");
    foreach (var (i, note) in notebook.Notes.Select((n, i) => (i, n)))
        Console.WriteLine($"  [{i + 1}] {note}");
    Console.WriteLine();
}

return;

