/// <summary>Web search and page-fetching tools.</summary>
static class WebSearchTool
{
    private static readonly HttpClient Http = new()
    {
        DefaultRequestHeaders =
        {
            { "User-Agent", "ResearchAgent/1.0" },
            { "Accept", "text/html" },
        },
        Timeout = TimeSpan.FromSeconds(15),
    };

    [Description("Search the web for a query and return a list of result snippets with URLs. Use this to discover relevant pages.")]
    public static async Task<string> SearchWeb(
        [Description("The search query string")] string query)
    {
        Console.WriteLine($"    🌐 SearchWeb(\"{query}\")");
        try
        {
            // Use DuckDuckGo Lite (HTML) — no API key required
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://lite.duckduckgo.com/lite/?q={encoded}";
            var html = await Http.GetStringAsync(url);
            var snippets = ParseDuckDuckGoLite(html);
            return snippets.Length > 0
                ? string.Join("\n\n", snippets)
                : "No results found. Try a different query.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    [Description("Fetch the text content of a web page given its URL. Returns the first ~4000 characters of visible text.")]
    public static async Task<string> FetchPage(
        [Description("The full URL of the page to fetch")] string url)
    {
        Console.WriteLine($"    📄 FetchPage(\"{url}\")");
        try
        {
            var html = await Http.GetStringAsync(url);
            var text = StripHtml(html);
            return text.Length > 4000 ? text[..4000] + "\n…[truncated]" : text;
        }
        catch (Exception ex)
        {
            return $"Failed to fetch page: {ex.Message}";
        }
    }

    // Rough HTML-to-text extraction
    private static string StripHtml(string html)
    {
        // Remove script/style blocks
        html = System.Text.RegularExpressions.Regex.Replace(
            html, @"<(script|style)[^>]*>[\s\S]*?</\1>", "", System.Text.RegularExpressions.RegexOptions.IgnoreCase);
        // Remove tags
        html = System.Text.RegularExpressions.Regex.Replace(html, @"<[^>]+>", " ");
        // Collapse whitespace
        html = System.Text.RegularExpressions.Regex.Replace(html, @"\s+", " ");
        return System.Net.WebUtility.HtmlDecode(html).Trim();
    }

    private static string[] ParseDuckDuckGoLite(string html)
    {
        // DuckDuckGo Lite returns results in <a> tags with class "result-link" and
        // snippets in <td> with class "result-snippet". We do a simple regex parse.
        var results = new List<string>();
        var linkMatches = System.Text.RegularExpressions.Regex.Matches(
            html, @"<a[^>]+class=""result-link""[^>]*href=""([^""]+)""[^>]*>(.*?)</a>",
            System.Text.RegularExpressions.RegexOptions.IgnoreCase | System.Text.RegularExpressions.RegexOptions.Singleline);
        var snippetMatches = System.Text.RegularExpressions.Regex.Matches(
            html, @"<td[^>]+class=""result-snippet""[^>]*>(.*?)</td>",
            System.Text.RegularExpressions.RegexOptions.IgnoreCase | System.Text.RegularExpressions.RegexOptions.Singleline);

        for (var i = 0; i < Math.Min(linkMatches.Count, 8); i++)
        {
            var link = System.Net.WebUtility.HtmlDecode(linkMatches[i].Groups[1].Value).Trim();
            var title = StripHtml(linkMatches[i].Groups[2].Value).Trim();
            var snippet = i < snippetMatches.Count
                ? StripHtml(snippetMatches[i].Groups[1].Value).Trim()
                : "";
            results.Add($"[{i + 1}] {title}\n    URL: {link}\n    {snippet}");
        }

        return results.ToArray();
    }
}

/// <summary>Note-taking tool for the agent to collect research findings.</summary>
class Notebook
{
    public List<string> Notes { get; } = [];

    [Description("Save a research note. Use this to record key facts, quotes, or findings along with the source URL.")]
    public string SaveNote(
        [Description("The note content including source URL")] string note)
    {
        Notes.Add(note);
        Console.WriteLine($"    📝 Note saved ({Notes.Count} total)");
        return $"Note #{Notes.Count} saved successfully.";
    }

    [Description("List all notes saved so far. Use this to review collected research before writing the summary.")]
    public string ListNotes()
    {
        if (Notes.Count == 0)
            return "No notes saved yet.";

        return string.Join("\n", Notes.Select((n, i) => $"[{i + 1}] {n}"));
    }
